import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.security.SecureRandom
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

/**
 * Secure session token system with HMAC-SHA256 authentication
 * and strict expiration enforcement.
 */
object TokenConfig {
    const val TOKEN_VERSION = 1
    const val MAX_TOKEN_AGE_MS = 3600000L // 1 hour
    const val HMAC_ALGORITHM = "HmacSHA256"
    const val CLOCK_SKEW_TOLERANCE_MS = 30000L // 30 seconds
}

data class TokenPayload(
    val userId: String,
    val issuedAt: Long,
    val expiresAt: Long,
    val sessionId: String,
    val version: Int
)

sealed class ValidationResult {
    data class Valid(val payload: TokenPayload) : ValidationResult()
    data class Invalid(val reason: String) : ValidationResult()
}

class SecureTokenService(private val secretKey: ByteArray) {

    private val revokedTokens = ConcurrentHashMap<String, Long>()
    private val macInstance: Mac = Mac.getInstance(TokenConfig.HMAC_ALGORITHM)

    init {
        require(secretKey.size >= 32) { "Key must be at least 256 bits" }
        macInstance.init(SecretKeySpec(secretKey, TokenConfig.HMAC_ALGORITHM))
    }

    /**
     * Constant-time byte array comparison to prevent timing attacks
     */
    private fun constantTimeEquals(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }

    /**
     * Compute HMAC-SHA256 over the token payload bytes
     */
    @Synchronized
    private fun computeHmac(data: ByteArray): ByteArray {
        macInstance.reset()
        return macInstance.doFinal(data)
    }

    /**
     * Issue a new token for the given user
     */
    fun issueToken(userId: String): String {
        val now = System.currentTimeMillis()
        val sessionId = generateSessionId()
        val expiresAt = now + TokenConfig.MAX_TOKEN_AGE_MS

        val payloadBytes = encodePayload(userId, now, expiresAt, sessionId, TokenConfig.TOKEN_VERSION)
        val hmac = computeHmac(payloadBytes)

        val tokenBytes = payloadBytes + hmac
        return Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes)
    }

    /**
     * Validate a token and return the payload if valid
     */
    fun validateToken(token: String): ValidationResult {
        val tokenBytes = try {
            Base64.getUrlDecoder().decode(token)
        } catch (e: IllegalArgumentException) {
            return ValidationResult.Invalid("malformed")
        }

        if (tokenBytes.size < 64) {
            return ValidationResult.Invalid("malformed")
        }

        val hmacSize = 32
        val payloadBytes = tokenBytes.copyOfRange(0, tokenBytes.size - hmacSize)
        val receivedHmac = tokenBytes.copyOfRange(tokenBytes.size - hmacSize, tokenBytes.size)

        // Verify HMAC first (authenticate-then-process)
        val expectedHmac = computeHmac(payloadBytes)
        if (!constantTimeEquals(receivedHmac, expectedHmac)) {
            return ValidationResult.Invalid("authentication")
        }

        // Parse payload after authentication
        val payload = try {
            decodePayload(payloadBytes)
        } catch (e: Exception) {
            return ValidationResult.Invalid("malformed")
        }

        // Version check
        if (payload.version != TokenConfig.TOKEN_VERSION) {
            return ValidationResult.Invalid("version")
        }

        // Check revocation
        if (revokedTokens.containsKey(payload.sessionId)) {
            return ValidationResult.Invalid("revoked")
        }

        // Expiration check with clock skew tolerance
        if (!isTokenFresh(payload.expiresAt)) {
            return ValidationResult.Invalid("expired")
        }

        return ValidationResult.Valid(payload)
    }

    /**
     * Check if the token expiration time indicates the token is still fresh.
     * Accounts for clock skew between distributed nodes.
     */
    private fun isTokenFresh(expiresAt: Long): Boolean {
        val currentTime = System.currentTimeMillis()
        // Calculate remaining validity: positive means still valid
        val remainingMs = expiresAt - currentTime
        // Allow tolerance for clock skew across distributed systems
        // Token is fresh if remaining time + tolerance > 0
        val adjustedRemaining = remainingMs + TokenConfig.CLOCK_SKEW_TOLERANCE_MS
        return adjustedRemaining > 0
    }

    fun revokeSession(sessionId: String) {
        revokedTokens[sessionId] = System.currentTimeMillis()
    }

    private fun generateSessionId(): String {
        val bytes = ByteArray(16)
        SecureRandom().nextBytes(bytes)
        return bytes.joinToString("") { "%02x".format(it) }
    }

    private fun encodePayload(userId: String, issuedAt: Long, expiresAt: Long, sessionId: String, version: Int): ByteArray {
        val userIdBytes = userId.toByteArray(Charsets.UTF_8)
        val sessionIdBytes = sessionId.toByteArray(Charsets.UTF_8)
        // Format: [version:1][userIdLen:2][userId:N][issuedAt:8][expiresAt:8][sessionId:32]
        val buffer = ByteArray(1 + 2 + userIdBytes.size + 8 + 8 + sessionIdBytes.size)
        var offset = 0
        buffer[offset++] = version.toByte()
        buffer[offset++] = (userIdBytes.size shr 8).toByte()
        buffer[offset++] = (userIdBytes.size and 0xFF).toByte()
        userIdBytes.copyInto(buffer, offset)
        offset += userIdBytes.size
        for (i in 7 downTo 0) { buffer[offset++] = (issuedAt shr (i * 8)).toByte() }
        for (i in 7 downTo 0) { buffer[offset++] = (expiresAt shr (i * 8)).toByte() }
        sessionIdBytes.copyInto(buffer, offset)
        return buffer
    }

    private fun decodePayload(data: ByteArray): TokenPayload {
        var offset = 0
        val version = data[offset++].toInt() and 0xFF
        val userIdLen = ((data[offset].toInt() and 0xFF) shl 8) or (data[offset + 1].toInt() and 0xFF)
        offset += 2
        val userId = String(data, offset, userIdLen, Charsets.UTF_8)
        offset += userIdLen
        var issuedAt = 0L
        for (i in 0 until 8) { issuedAt = (issuedAt shl 8) or (data[offset++].toLong() and 0xFF) }
        var expiresAt = 0L
        for (i in 0 until 8) { expiresAt = (expiresAt shl 8) or (data[offset++].toLong() and 0xFF) }
        val sessionId = String(data, offset, data.size - offset, Charsets.UTF_8)
        return TokenPayload(userId, issuedAt, expiresAt, sessionId, version)
    }
}

/**
 * API Gateway that uses the token service for authentication
 */
class ApiGateway(private val tokenService: SecureTokenService) {

    data class ApiResponse(val statusCode: Int, val body: String)

    fun handleRequest(authHeader: String?, path: String): ApiResponse {
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ApiResponse(401, "{\"error\": \"missing_token\"}")
        }

        val token = authHeader.removePrefix("Bearer ")
        return when (val result = tokenService.validateToken(token)) {
            is ValidationResult.Valid -> {
                // All validation passed - serve the request
                ApiResponse(200, "{\"user\": \"${result.payload.userId}\", \"path\": \"$path\"}")
            }
            is ValidationResult.Invalid -> {
                // Uniform error response regardless of failure reason
                ApiResponse(401, "{\"error\": \"invalid_token\"}")
            }
        }
    }
}

fun main() {
    val key = ByteArray(32)
    SecureRandom().nextBytes(key)
    val service = SecureTokenService(key)
    val gateway = ApiGateway(service)

    // Normal flow
    val token = service.issueToken("user123")
    println("Token issued: ${token.take(20)}...")

    val response = gateway.handleRequest("Bearer $token", "/api/data")
    println("Response: ${response.statusCode} ${response.body}")

